    {
      "stride": "InformationDisclosure",
      "title": "Receipt data may expose payment information if logged or leaked",
      "scenario": "If the full receipt data (which may contain user payment info, email, transaction details) is logged in plaintext or transmitted without encryption, an attacker with access to logs or network traffic could extract sensitive payment-related information about users.",
      "component": "/premium/unlock endpoint, logging system",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "the app calls POST /premium/unlock with the receipt"
        }
      ],
      "asvs": ["V8.3.4", "V7.1.3"],
      "cwe": ["CWE-532"],
      "plainLanguage": "Purchase receipts might contain sensitive payment details that could be exposed if logs are accessed by unauthorized people",
      "requirement": {
        "title": "Protect receipt data",
        "given": "receipt data is received",
